
# ============================================================
# GSE122960: Single-cell RNA-seq analysis
# ============================================================
#
# This script performs downstream analyses using a preprocessed
# Seurat object with cell-type annotations generated by Sc-type.
#
# The input Seurat object must contain:
#   - UMAP coordinates
#   - The "condition" metadata column
#   - The "sctype_classification" metadata column
#
# The original Seurat object was generated and annotated by a
# previous researcher. The analyses below were performed
# independently using this pre-existing object.
#
# ============================================================


#--------------------------
# 1. Load required packages
#--------------------------

library(Seurat)
library(SeuratObject)
library(dplyr)
library(ggplot2)
library(patchwork)
library(ggrepel)


#--------------------------
# 2. Load the preprocessed Seurat object
#--------------------------

integrated_seurat <- readRDS("integrated_seurat.rds")

# Inspect the Seurat object
integrated_seurat
head(integrated_seurat)

# Check whether the required metadata columns are available
required_metadata <- c("condition", "sctype_classification")

if (!all(required_metadata %in% colnames(integrated_seurat@meta.data))) {
  stop("The input Seurat object must contain 'condition' and 'sctype_classification' metadata columns.")
}

# Check the existing UMAP embedding
DimPlot(
  integrated_seurat,
  reduction = "umap",
  group.by = "seurat_clusters",
  label = TRUE
)


#--------------------------
# 3. Visualization based on Sc-type cell-type annotations
#--------------------------

# Convert "Donor" to "Control"
integrated_seurat$condition <- as.character(integrated_seurat$condition)
integrated_seurat$condition[integrated_seurat$condition == "Donor"] <- "Control"

integrated_seurat$condition <- factor(
  integrated_seurat$condition,
  levels = c("Control", "IPF")
)

# Convert cell-type annotations to character for label replacement
integrated_seurat$sctype_classification <- as.character(
  integrated_seurat$sctype_classification
)

# Replace selected cell-type labels
integrated_seurat$sctype_classification[
  integrated_seurat$sctype_classification == "Cancer stem cells"
] <- "Basophils"

integrated_seurat$sctype_classification[
  integrated_seurat$sctype_classification == "Endothelial cell"
] <- "Endothelial cells"

integrated_seurat$sctype_classification <- as.factor(
  integrated_seurat$sctype_classification
)


# Define colors and display order
cell_colors <- c(
  "Fibroblasts" = "red",
  "Endothelial cells" = "lightgreen",
  "Ciliated cells" = "gold",
  "Pulmonary alveolar type I cells" = "darkgreen",
  "Pulmonary alveolar type II cells" = "green",
  "Alveolar macrophages" = "lightpink",
  "Immune system cells" = "hotpink",
  "Basophils" = "gray"
)

cell_order <- c(
  "Basophils",
  "Immune system cells",
  "Alveolar macrophages",
  "Pulmonary alveolar type II cells",
  "Pulmonary alveolar type I cells",
  "Ciliated cells",
  "Endothelial cells",
  "Fibroblasts"
)


# UMAP plot by cell type
DimPlot(
  integrated_seurat,
  group.by = "sctype_classification",
  cols = cell_colors,
  order = cell_order,
  label = FALSE,
  label.size = 20
) +
  theme_classic() +
  theme(
    legend.position = "right",
    legend.text = element_text(size = 18),
    axis.title = element_text(size = 20),
    axis.text = element_text(size = 20)
  ) +
  labs(
    x = "UMAP_1",
    y = "UMAP_2"
  )


#--------------------------
# 4. Violin plots of gene expression across cell types
#--------------------------

# Specify the order of cell types
integrated_seurat$sctype_classification <- factor(
  integrated_seurat$sctype_classification,
  levels = c(
    "Fibroblasts",
    "Endothelial cells",
    "Ciliated cells",
    "Pulmonary alveolar type I cells",
    "Pulmonary alveolar type II cells",
    "Alveolar macrophages",
    "Immune system cells",
    "Basophils"
  )
)

# TGFB1I1 expression by cell type and condition
VlnPlot(
  object = integrated_seurat,
  features = c("TGFB1I1"),
  group.by = "sctype_classification",
  split.by = "condition",
  cols = c("skyblue", "tomato"),
  pt.size = 0.2
) +
  theme(
    axis.text.x = element_text(
      angle = 45,
      hjust = 1,
      size = 18
    )
  )


# Create abbreviated cell-type labels
integrated_seurat$sctype_abbr <- integrated_seurat$sctype_classification

integrated_seurat$sctype_abbr <- plyr::revalue(
  integrated_seurat$sctype_abbr,
  c(
    "Basophils" = "Baso",
    "Immune system cells" = "Immune",
    "Alveolar macrophages" = "AM",
    "Pulmonary alveolar type II cells" = "AT2",
    "Pulmonary alveolar type I cells" = "AT1",
    "Ciliated cells" = "Ciliated",
    "Endothelial cells" = "Endo",
    "Fibroblasts" = "Fibro"
  )
)

# Specify the display order of abbreviated labels
integrated_seurat$sctype_abbr <- factor(
  integrated_seurat$sctype_abbr,
  levels = c(
    "Fibro",
    "AT1",
    "AT2",
    "Ciliated",
    "Endo",
    "AM",
    "Immune",
    "Baso"
  )
)

# TGFB1I1 expression using abbreviated cell-type labels
VlnPlot(
  object = integrated_seurat,
  features = "TGFB1I1",
  group.by = "sctype_abbr",
  split.by = "condition",
  cols = c("skyblue", "tomato"),
  pt.size = 0.2
) +
  theme(
    legend.position = "right",
    legend.text = element_text(size = 18),
    axis.title = element_text(size = 20),
    axis.text = element_text(size = 20)
  ) +
  theme(
    axis.text.x = element_text(
      angle = 0,
      hjust = 0.5,
      size = 18
    )
  )


# Stacked violin plots of fibrosis-related gene expression
VlnPlot(
  object = integrated_seurat,
  features = c(
    "TGFB1I1",
    "ACTA2",
    "COL1A1",
    "COL1A2",
    "CTHRC1"
  ),
  group.by = "sctype_abbr",
  split.by = "condition",
  cols = c("blue", "red"),
  stack = TRUE
)


#--------------------------
# 5. Feature plot of TGFB1I1 in all cells
#--------------------------

# Check the number of cells in each condition
table(integrated_seurat$condition)

# Set a random seed for reproducibility
set.seed(123)

# Obtain cell IDs for each condition
IPF_cells <- WhichCells(
  integrated_seurat,
  expression = condition == "IPF"
)

control_cells <- WhichCells(
  integrated_seurat,
  expression = condition == "Control"
)

# Randomly downsample Control cells to match the number of IPF cells
control_down <- sample(
  control_cells,
  size = length(IPF_cells)
)

# Create a downsampled Seurat object
downsampled_cells <- c(IPF_cells, control_down)

seurat_down <- subset(
  integrated_seurat,
  cells = downsampled_cells
)

# Check the number of cells after downsampling
table(seurat_down$condition)

# Feature plot of TGFB1I1
p <- FeaturePlot(
  seurat_down,
  features = "TGFB1I1",
  cols = c("lightgray", "red"),
  split.by = "condition",
  pt.size = 0.1,
  min.cutoff = 0,
  max.cutoff = 2
)

p + plot_annotation(
  title = "TGFB1I1",
  caption = "Control vs IPF"
) &
  theme(
    legend.text = element_text(size = 18),
    axis.title = element_text(size = 20),
    axis.text = element_text(size = 20)
  ) +
  labs(
    x = "UMAP_1",
    y = "UMAP_2"
  )


#--------------------------
# 6. Differential expression analysis in fibroblasts
#--------------------------

# Extract fibroblasts using the existing Sc-type annotations
Idents(integrated_seurat) <- "sctype_classification"

fibro <- subset(
  integrated_seurat,
  idents = "Fibroblasts"
)

# Check the number of fibroblasts in each condition
table(fibro$condition)


#--------------------------
# 6.1. Identification of TGFB1I1-positive and -negative cells
#--------------------------

DefaultAssay(fibro) <- "RNA"

# Retrieve raw count data
counts <- GetAssayData(
  fibro,
  slot = "counts"
)

# Classify fibroblasts according to TGFB1I1 expression
fibro$TGFB1I1_status <- ifelse(
  counts["TGFB1I1", ] > 0,
  "positive",
  "negative"
)

# Extract cell IDs for each condition
control_cells_ids <- rownames(fibro@meta.data)[
  fibro$condition == "Control"
]

ipf_cells_ids <- rownames(fibro@meta.data)[
  fibro$condition == "IPF"
]


#--------------------------
# 6.2. Differential expression analysis
#--------------------------

# Control: TGFB1I1-positive vs TGFB1I1-negative fibroblasts
DE_control <- FindMarkers(
  object = fibro,
  ident.1 = "positive",
  ident.2 = "negative",
  group.by = "TGFB1I1_status",
  cells = control_cells_ids,
  test.use = "wilcox"
) %>%
  tibble::rownames_to_column("gene")


# IPF: TGFB1I1-positive vs TGFB1I1-negative fibroblasts
DE_ipf <- FindMarkers(
  object = fibro,
  ident.1 = "positive",
  ident.2 = "negative",
  group.by = "TGFB1I1_status",
  cells = ipf_cells_ids,
  test.use = "wilcox"
) %>%
  tibble::rownames_to_column("gene")


#--------------------------
# 6.3. Prepare differential expression results for visualization
#--------------------------

format_DE <- function(df) {
  df %>%
    mutate(
      negLog10p = -log10(p_val_adj + 1e-10),
      color_group = case_when(
        p_val_adj < 0.05 & abs(avg_log2FC) > 0.25 ~ "significant",
        TRUE ~ "ns"
      )
    )
}

DE_control <- format_DE(DE_control)
DE_ipf <- format_DE(DE_ipf)


#--------------------------
# 6.4. Volcano plot function
#--------------------------

# Genes to label in the volcano plots
genes_to_label <- c(
  "ACTA2",
  "MYH11",
  "TAGLN"
)

volcano_plot <- function(df, title) {
  
  # Exclude TGFB1I1 from the volcano plot
  df <- df %>%
    filter(gene != "TGFB1I1")
  
  # Classify genes as upregulated, downregulated, or not significant
  df <- df %>%
    mutate(
      color_group = case_when(
        p_val_adj < 0.05 & avg_log2FC > 0.25 ~ "up",
        p_val_adj < 0.05 & avg_log2FC < -0.25 ~ "down",
        TRUE ~ "ns"
      )
    )
  
  ggplot(
    df,
    aes(
      x = avg_log2FC,
      y = negLog10p
    )
  ) +
    geom_point(
      aes(color = color_group),
      alpha = 0.6,
      size = 1.5
    ) +
    scale_color_manual(
      values = c(
        "up" = "red",
        "down" = "blue",
        "ns" = "grey70"
      )
    ) +
    geom_vline(
      xintercept = c(-0.25, 0.25),
      linetype = "dashed"
    ) +
    geom_hline(
      yintercept = -log10(0.05),
      linetype = "dashed"
    ) +
    coord_cartesian(
      xlim = c(-4, 4)
    ) +
    geom_text_repel(
      data = df %>%
        filter(gene %in% genes_to_label),
      aes(label = gene),
      size = 5,
      max.overlaps = 20
    ) +
    labs(
      x = "log2 fold change",
      y = "-log10(adjusted P-value)",
      title = title
    ) +
    theme_minimal() +
    theme(
      legend.position = "none",
      legend.text = element_text(size = 18),
      axis.title = element_text(size = 20),
      axis.text = element_text(size = 20)
    )
}


#--------------------------
# 6.5. Generate volcano plots
#--------------------------

p1 <- volcano_plot(
  DE_control,
  "Control: TGFB1I1+ vs TGFB1I1-"
)

p2 <- volcano_plot(
  DE_ipf,
  "IPF: TGFB1I1+ vs TGFB1I1-"
)

# Display the two volcano plots side by side
p1 + p2


#--------------------------
# 7. Record the analysis environment
#--------------------------

sessionInfo()
